const data = Uint8Array.from([1, 2, 3, 4, 5]);
const view = data.subarray(1, 4);
const copy = data.slice(1, 4);

view[0] = 20;
copy[1] = 30;
data[3] = 40;

console.log(view.join(","));
console.log(copy.join(","));
console.log(data.join(","));
console.log(view.buffer === data.buffer, copy.buffer === data.buffer);
